{"content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ARTIFACT: Museum Night — 18 October 2026, The Old Gallery, Warsaw</title>
<meta name="description" content="ARTIFACT: Museum Night — a cinematic after-hours museum event on 18 October 2026 at The Old Gallery, Warsaw. Exhibitions, live performances, artist talks, and guided tours after dark.">
<meta name="og:title" content="ARTIFACT: Museum Night">
<meta name="og:description" content="A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours. 18 October 2026, The Old Gallery, Warsaw.">
<meta name="og:image" content="https://source.unsplash.com/featured/1200x630?museum,night">
<meta name="og:type" content="website">
<meta name="theme-color" content="#070506">
<link rel="icon" type="image/svg+xml" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='6' fill='%23070506'/><text x='50%25' y='55%25' dominant-baseline='middle' text-anchor='middle' font-family='Georgia,serif' font-size='18' fill='%23d6ad60'>A</text></svg>">
<style>
:root{
  --bg:#070506;
  --velvet:#1a0710;
  --burgundy:#3a0f1d;
  --midnight:#07111f;
  --gold:#d6ad60;
  --soft-gold:#f3d79b;
  --ivory:#f8efe2;
  --muted:#b9a999;
  --panel:rgba(255,244,220,0.06);
  --border:rgba(214,173,96,0.28);
  --serif:Georgia,'Times New Roman',serif;
  --sans:Inter,system-ui,'Segoe UI',sans-serif;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:var(--sans);
  background:var(--bg);
  color:var(--ivory);
  line-height:1.6;
  overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
body::before{
  content:"";
  position:fixed;
  inset:0;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.06'/%3E%3C/svg%3E");
  pointer-events:none;
  z-index:1000;
  opacity:0.5;
  mix-blend-mode:overlay;
}
.wrap{max-width:1280px;margin:0 auto;padding:0 24px}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none;color:inherit}
:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
img{display:block;max-width:100%}

/* NAV */
.nav{
  position:sticky;top:0;z-index:100;
  background:rgba(7,5,6,0.82);
  backdrop-filter:blur(14px);
  -webkit-backdrop-filter:blur(14px);
  border-bottom:1px solid var(--border);
}
.nav-inner{display:flex;align-items:center;justify-content:space-between;height:68px}
.brand{font-family:var(--serif);font-size:22px;letter-spacing:0.18em;color:var(--gold);font-weight:400}
.brand span{color:var(--ivory)}
.nav-links{display:flex;gap:32px;align-items:center}
.nav-links a{font-size:14px;letter-spacing:0.06em;color:var(--muted);transition:color .25s}
.nav-links a:hover{color:var(--ivory)}
.nav-links a.active{color:var(--gold)}
.nav-cta{
  background:var(--gold);color:var(--bg);
  padding:10px 20px;border-radius:2px;
  font-size:13px;letter-spacing:0.12em;text-transform:uppercase;font-weight:600;
  transition:background .25s,transform .25s;
}
.nav-cta:hover{background:var(--soft-gold);transform:translateY(-1px)}
.mobile-toggle{display:none;background:none;color:var(--ivory);font-size:22px;padding:4px}
@media(max-width:880px){
  .nav-links{
    position:absolute;top:68px;left:0;right:0;
    flex-direction:column;background:rgba(7,5,6,0.98);
    padding:20px 24px;gap:18px;border-bottom:1px solid var(--border);
    transform:translateY(-120%);opacity:0;pointer-events:none;
    transition:transform .35s ease,opacity .35s ease;
  }
  .nav-links.open{transform:translateY(0);opacity:1;pointer-events:auto}
  .mobile-toggle{display:block}

}

/* HERO */
.hero{
  position:relative;min-height:92vh;
  display:flex;align-items:center;
  overflow:hidden;
  background:
    radial-gradient(1200px 600px at 70% -10%, rgba(214,173,96,0.18), transparent 60%),
    radial-gradient(900px 500px at 10% 30%, rgba(58,15,29,0.55), transparent 70%),
    linear-gradient(180deg, var(--midnight) 0%, var(--bg) 100%);
}
.hero-img{
  position:absolute;inset:0;width:100%;height:100%;
  object-fit:cover;
  filter:blur(1px) brightness(0.42) contrast(1.08) saturate(0.7);
  transform:scale(1.02);
}
.hero-overlay{
  position:absolute;inset:0;
  background:
    radial-gradient(60% 50% at 30% 20%, transparent 0%, rgba(7,5,6,0.55) 100%),
    linear-gradient(180deg, rgba(7,5,6,0.2) 0%, rgba(7,5,6,0.75) 100%);
}
.hero-spotlight{
  position:absolute;inset:0;
  background:
    radial-gradient(40vw 30vh at 20% 15%, rgba(243,215,155,0.10), transparent 70%),
    radial-gradient(30vw 25vh at 80% 25%, rgba(214,173,96,0.08), transparent 70%);
}
.hero-content{position:relative;z-index:5;padding:80px 0}
.hero-eyebrow{
  display:inline-flex;gap:10px;align-items:center;
  font-size:12px;letter-spacing:0.28em;text-transform:uppercase;color:var(--muted);
  border:1px solid var(--border);padding:8px 14px;border-radius:2px;
  background:var(--panel);
}
.hero-eyebrow .dot{width:6px;height:6px;border-radius:50%;background:var(--gold);box-shadow:0 0 10px var(--gold)}
.hero-title{
  font-family:var(--serif);
  font-size:clamp(48px,9vw,112px);
  line-height:1.04;font-weight:400;
  letter-spacing:-0.01em;
  margin:28px 0 18px;
  color:var(--ivory);
  text-shadow:0 2px 30px rgba(0,0,0,0.6);
}
.hero-title em{font-style:italic;color:var(--gold)}
.hero-event{
  font-family:var(--serif);font-size:clamp(22px,3.4vw,34px);
  letter-spacing:0.14em;color:var(--soft-gold);
  margin-bottom:36px;
}
.hero-meta{
  display:flex;flex-wrap:wrap;gap:14px 28px;
  font-size:14px;color:var(--muted);margin-bottom:40px;
  padding-bottom:24px;border-bottom:1px solid var(--border);
}
.hero-meta strong{color:var(--ivory);font-weight:500;display:block;font-size:12px;letter-spacing:0.16em;text-transform:uppercase;margin-bottom:4px}
.hero-cta{display:flex;gap:16px;flex-wrap:wrap}
.btn{
  display:inline-flex;align-items:center;gap:10px;
  padding:14px 26px;border-radius:2px;
  font-size:13px;letter-spacing:0.14em;text-transform:uppercase;font-weight:600;
  transition:all .25s;border:1px solid transparent;
}
.btn-primary{background:var(--gold);color:var(--bg)}
.btn-primary:hover{background:var(--soft-gold);transform:translateY(-2px);box-shadow:0 8px 24px rgba(214,173,96,0.35)}
.btn-ghost{background:transparent;color:var(--ivory);border-color:var(--border)}
.btn-ghost:hover{border-color:var(--gold);color:var(--gold);transform:translateY(-2px)}
.btn-arrow{color:var(--bg);font-size:16px}
.btn-ghost .btn-arrow{color:var(--ivory)}
.btn-ghost:hover .btn-arrow{color:var(--gold)}

.hero-badges{margin-top:48px;display:flex;flex-wrap:wrap;gap:10px}
.badge{
  font-size:11px;letter-spacing:0.18em;text-transform:uppercase;
  padding:7px 12px;border-radius:2px;
  border:1px solid var(--border);color:var(--muted);
  background:var(--panel);
}
.badge.gold{color:var(--gold);border-color:var(--gold)}
.badge i{font-style:normal;color:var(--soft-gold)}

/* SECTION HEADER */
.section{padding:96px 0;position:relative}
.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:32px;margin-bottom:56px;flex-wrap:wrap}
.section-eyebrow{font-size:12px;letter-spacing:0.28em;text-transform:uppercase;color:var(--gold);margin-bottom:14px}
.section-title{font-family:var(--serif);font-size:clamp(34px,5.4vw,56px);font-weight:400;line-height:1.1;letter-spacing:-0.01em}
.section-title em{font-style:italic;color:var(--gold)}
.section-cta{font-size:13px;letter-spacing:0.1em;color:var(--muted)}
.section-cta a{color:var(--gold);text-decoration:underline;text-underline-offset:6px}

/* INTRO */
.intro-text{
  font-size:18px;line-height:1.75;max-width:680px;color:var(--muted);
  margin-bottom:48px;
}
.intro-text strong{color:var(--ivory);font-weight:500}
.intro-text em{color:var(--gold);font-style:italic}

.features{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
@media(max-width:880px){.features{grid-template-columns:1fr}}
.feature{
  background:var(--panel);
  border:1px solid var(--border);
  border-radius:3px;
  padding:36px 30px;
  transition:transform .3s,border-color .3s,background .3s;
  position:relative;overflow:hidden;
}
.feature::before{
  content:"";position:absolute;top:0;left:0;width:3px;height:100%;
  background:linear-gradient(180deg,transparent,var(--gold),transparent);
  opacity:0;transition:opacity .3s;
}
.feature:hover{transform:translateY(-6px);border-color:var(--gold);background:rgba(214,173,96,0.08)}
.feature:hover::before{opacity:1}
.feature-icon{
  font-family:var(--serif);font-size:38px;color:var(--gold);
  margin-bottom:18px;line-height:1;
}
.feature h3{font-family:var(--serif);font-size:22px;font-weight:400;margin-bottom:12px;color:var(--ivory)}
.feature p{font-size:14px;color:var(--muted);line-height:1.65}

/* TIMELINE */
.timeline{position:relative;padding-left:0}
.timeline::before{
  content:"";position:absolute;left:8px;top:8px;bottom:8px;width:1px;
  background:linear-gradient(180deg,transparent,var(--gold),var(--gold),transparent);
  opacity:0.4;
}
.timeline-item{
  display:grid;grid-template-columns:120px 1fr;gap:32px;
  padding:24px 0;border-bottom:1px solid rgba(214,173,96,0.12);
  position:relative;
}
.timeline-item:last-child{border-bottom:none}
.tl-time{
  font-family:var(--serif);font-size:30px;color:var(--gold);
  letter-spacing:0.04em;font-weight:400;
  padding-top:2px;
}
.tl-time .ampm{display:block;font-size:12px;letter-spacing:0.18em;color:var(--muted);text-transform:uppercase;margin-top:2px}
.tl-body h4{font-family:var(--serif);font-size:20px;font-weight:400;color:var(--ivory);margin-bottom:6px}
.tl-body p{font-size:14px;color:var(--muted);line-height:1.6;margin-bottom:10px}
.tl-loc{
  display:inline-flex;align-items:center;gap:8px;
  font-size:12px;letter-spacing:0.1em;text-transform:uppercase;
  color:var(--gold);border:1px solid var(--border);
  padding:4px 10px;border-radius:2px;background:var(--panel);
}
.tl-dot{
  position:absolute;left:-18px;top:30px;width:14px;height:14px;border-radius:50%;
  background:var(--bg);border:1px solid var(--gold);
}
.tl-item.revealed .tl-dot{background:var(--gold);box-shadow:0 0 12px var(--gold)}
.tl-item.revealed .tl-time{color:var(--soft-gold)}

/* ARTISTS */
.artists-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
@media(max-width:1100px){.artists-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:760px){.artists-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:480px){.artists-grid{grid-template-columns:1fr}}
.artist-card{
  background:var(--panel);
  border:1px solid var(--border);
  border-radius:3px;
  overflow:hidden;
  transition:transform .3s,border-color .3s;
  cursor:pointer;
}
.artist-card:hover{transform:translateY(-5px);border-color:var(--gold)}
.artist-img{
  width:100%;aspect-ratio:4/3;object-fit:cover;
  filter:brightness(0.7) saturate(0.8);
  transition:filter .4s;
  background:var(--velvet);
}
.artist-card:hover .artist-img{filter:brightness(0.85) saturate(0.95)}
.artist-body{padding:18px 18px 20px}
.artist-name{font-family:var(--serif);font-size:18px;color:var(--ivory);margin-bottom:4px}
.artist-role{font-size:12px;letter-spacing:0.14em;text-transform:uppercase;color:var(--gold);margin-bottom:10px}
.artist-teaser{font-size:13px;color:var(--muted);line-height:1.55;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.artist-link{
  display:inline-flex;align-items:center;gap:8px;
  margin-top:12px;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;
  color:var(--gold);border-bottom:1px solid var(--gold);
  padding-bottom:2px;transition:gap .25s;
}
.artist-card:hover .artist-link{gap:14px}

/* VENUE */
.venue-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
@media(max-width:880px){.venue-grid{grid-template-columns:1fr;gap:32px}}
.venue-info h3{font-family:var(--serif);font-size:26px;font-weight:400;color:var(--ivory);margin-bottom:8px}
.venue-address{font-size:14px;color:var(--muted);margin-bottom:28px;display:flex;gap:8px;align-items:center}
.venue-address .map-pin{color:var(--gold)}
.venue-tips{display:grid;gap:18px}
.venue-tip{
  display:flex;gap:14px;align-items:flex-start;
  padding:16px;background:var(--panel);border:1px solid var(--border);border-radius:2px;
}
.venue-tip .ti{pcolor:var(--gold);font-size:16px;margin-top:2px;flex-shrink:0}
.venue-tip h4{font-size:14px;color:var(--ivory);margin-bottom:4px;font-weight:500}
.venue-tip p{font-size:13px;color:var(--muted);line-height:1.55}
.venue-map{
  background:var(--panel);
  border:1px solid var(--border);
  border-radius:3px;
  padding:24px;
  aspect-ratio:1/1;
  max-width:480px;
}
.venue-map svg{width:100%;height:100%;display:block}

/* TICKETS */
.tickets-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:stretch}
@media(max-width:880px){.tickets-grid{grid-template-columns:1fr}}
.ticket{
  background:var(--panel);
  border:1px solid var(--border);
  border-radius:3px;
  padding:34px 28px;
  display:flex;flex-direction:column;
  position:relative;
  transition:transform .3s,border-color .3s,background .3s;
}
.ticket:hover{transform:translateY(-6px);border-color:var(--gold)}
.ticket.recommended{border-color:var(--gold);background:rgba(214,173,96,0.07)}
.ticket-rec{
  position:absolute;top:-12px;right:20px;
  background:var(--gold);color:var(--bg);
  font-size:11px;letter-spacing:0.16em;text-transform:uppercase;font-weight:600;
  padding:5px 12px;border-radius:2px;
}
.ticket-tier{font-family:var(--serif);font-size:26px;color:var(--ivory);margin-bottom:6px}
.ticket-price{font-family:var(--serif);font-size:44px;color:var(--gold);margin-bottom:4px;line-height:1}
.ticket-price small{font-size:14px;color:var(--muted);letter-spacing:0.1em;margin-left:6px;font-family:var(--sans)}
.ticket-desc{font-size:13px;color:var(--muted);margin-bottom:22px;min-height:20px}
.ticket-features{list-style:none;margin-bottom:24px}
.ticket-features li{
  font-size:13px;color:var(--muted);
  padding:7px 0;border-bottom:1px solid rgba(214,173,96,0.12);
  display:flex;gap:10px;align-items:flex-start;
}
.ticket-features li:last-child{border-bottom:none}
.ticket-features li::before{content:"✦";color:var(--gold);font-size:10px;margin-top:7px}
.ticket-btn{
  margin-top:auto;
  background:var(--gold);color:var(--bg);
  padding:12px 20px;border-radius:2px;
  font-size:12px;letter-spacing:0.14em;text-transform:uppercase;font-weight:600;
  transition:background .25s,transform .25s;
}
.ticket:hover .ticket-btn{background:var(--soft-gold)}
.ticket-btn:hover{transform:translateY(-2px)}

/* MODAL */
.modal-backdrop{
  position:fixed;inset:0;z-index:200;
  background:rgba(7,5,6,0.8);
  backdrop-filter:blur(6px);
  display:flex;align-items:center;justify-content:center;
  padding:24px;
  opacity:0;pointer-events:none;
  transition:opacity .3s;
}
.modal-backdrop.open{opacity:1;pointer-events:auto}
.modal{
  background:linear-gradient(180deg,var(--velvet),var(--bg));
  border:1px solid var(--border);
  border-radius:4px;
  width:100%;max-width:520px;max-height:90vh;overflow-y:auto;
  padding:36px;
  transform:translateY(20px) scale(0.98);
  transition:transform .3s;
}
.modal-backdrop.open .modal{transform:translateY(0) scale(1)}
.modal-close{
  position:absolute;top:14px;right:14px;
  width:34px;height:34px;border-radius:50%;
  background:var(--panel);border:1px solid var(--border);
  color:var(--muted);font-size:18px;display:flex;align-items:center;justify-content:center;
  transition:background .25s,color .25s;
}
.modal-close:hover{background:var(--gold);color:var(--bg)}
.modal h2{font-family:var(--serif);font-size:28px;color:var(--ivory);margin-bottom:6px}
.modal .modal-sub{font-size:13px;color:var(--muted);margin-bottom:24px}
.modal label{display:block;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:var(--muted);margin:18px 0 8px}
.modal input,.modal select{
  width:100%;padding:12px 14px;background:var(--panel);
  border:1px solid var(--border);border-radius:2px;
  color:var(--ivory);font-family:inherit;font-size:14px;
  transition:border-color .25s;
}
.modal input:focus,.modal select:focus{outline:none;border-color:var(--gold)}
.modal input.error{border-color:#c0392b}
.modal .modal-row{display:flex;gap:14px}
.modal .modal-row>*{flex:1}
.modal .total{
  display:flex;justify-content:space-between;align-items:center;
  margin:22px 0;padding:16px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);
}
.modal .total span{color:var(--muted);font-size:13px}
.modal .total strong{font-family:var(--serif);font-size:26px;color:var(--gold)}
.modal .terms{
  display:flex;gap:10px;align-items:flex-start;margin:18px 0;
  font-size:13px;color:var(--muted);
}
.modal .terms input{width:16px;height:16px;accent-color:var(--gold);margin-top:2px;flex-shrink:0}
.modal .modal-btn{
  width:100%;padding:14px;background:var(--gold);color:var(--bg);
  border-radius:2px;font-size:13px;letter-spacing:0.14em;text-transform:uppercase;font-weight:600;
  transition:background .25s,transform .25s;margin-top:8px;
}
.modal .modal-btn:hover{background:var(--soft-gold);transform:translateY(-1px)}
.modal .modal-btn:disabled{background:var(--muted);cursor:not-allowed;transform:none}
.modal-success{
  text-align:center;padding:20px 0;
}
.modal-success .check{
  width:64px;height:64px;border-radius:50%;
  background:var(--gold);color:var(--bg);
  display:flex;align-items:center;justify-content:center;
  font-size:30px;margin:0 auto 18px;
}
.modal-success h3{font-family:var(--serif);font-size:24px;color:var(--ivory);margin-bottom:8px}
.modal-success p{font-size:13px;color:var(--muted);margin-bottom:6px}

/* FAQ */
.faq-list{display:grid;gap:12px;max-width:760px}
.faq-item{
  background:var(--panel);
  border:1px solid var(--border);
  border-radius:3px;
  overflow:hidden;
  transition:border-color .3s;
}
.faq-item.active{border-color:var(--gold)}
.faq-q{
  width:100%;text-align:left;
  display:flex;align-items:center;justify-content:space-between;gap:20px;
  padding:20px 22px;
  font-family:var(--serif);font-size:18px;color:var(--ivory);
  transition:background .25s;
}
.faq-item:hover .faq-q{background:rgba(214,173,96,0.04)}
.faq-item.active .faq-q{background:rgba(214,173,96,0.08)}
.faq-q .icon{
  font-size:18px;color:var(--gold);transition:transform .3s;flex-shrink:0;
}
.faq-item.active .faq-q .icon{transform:rotate(45deg)}
.faq-a{
  max-height:0;overflow:hidden;
  transition:max-height .35s ease,padding .35s ease;
  padding:0 22px;
}
.faq-a-inner{padding-bottom:20px;font-size:14px;color:var(--muted);line-height:1.7}

/* NEWSLETTER */
.newsletter{
  background:linear-gradient(135deg,var(--velvet),var(--burgundy));
  border:1px solid var(--border);
  border-radius:4px;
  padding:56px;
  text-align:center;
  position:relative;overflow:hidden;
}
.newsletter::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(30% 40% at 30% 20%, rgba(214,173,96,0.12), transparent 70%);
  pointer-events:none;
}
.newsletter>*{position:relative}
.newsletter h2{font-family:var(--serif);font-size:clamp(28px,4vw,42px);font-weight:400;color:var(--ivory);margin-bottom:10px}
.newsletter p{font-size:14px;color:var(--muted);margin-bottom:28px;max-width:480px;margin-left:auto;margin-right:auto}
.newsletter-form{display:flex;gap:10px;max-width:460px;margin:0 auto;flex-wrap:wrap;justify-content:center}
.newsletter-form input{
  flex:1;min-width:220px;padding:13px 16px;
  background:var(--panel);border:1px solid var(--border);
  border-radius:2px;color:var(--ivory);font-family:inherit;font-size:14px;
}
.newsletter-form input:focus{outline:none;border-color:var(--gold)}
.newsletter-form input.error{border-color:#c0392b}
.newsletter-form button{
  background:var(--gold);color:var(--bg);
  padding:13px 24px;border-radius:2px;
  font-size:12px;letter-spacing:0.14em;text-transform:uppercase;font-weight:600;
  transition:background .25s,transform .25s;
}
.newsletter-form button:hover{background:var(--soft-gold);transform:translateY(-2px)}
.newsletter-note{font-size:12px;color:var(--muted);margin-top:16px;letter-spacing:0.06em}

/* FOOTER */
footer{
  border-top:1px solid var(--border);
  padding:60px 0 30px;
  background:linear-gradient(180deg,transparent,rgba(7,5,6,0.6));
}
.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:40px;margin-bottom:40px}
@media(max-width:880px){.footer-grid{grid-template-columns:1fr 1fr;gap:28px}}
@media(max-width:520px){.footer-grid{grid-template-columns:1fr}}
.footer-brand{font-family:var(--serif);font-size:22px;letter-spacing:0.18em;color:var(--gold);margin-bottom:10px}
.footer-brand span{color:var(--ivory)}
.footer-credits{font-size:13px;color:var(--muted);line-height:1.6}
.footer-col h5{font-size:11px;letter-spacing:0.2em;text-transform:uppercase;color:var(--gold);margin-bottom:14px}
.footer-col a{display:block;font-size:13px;color:var(--muted);margin-bottom:8px;transition:color .2s}
.footer-col a:hover{color:var(--ivory)}
.footer-bottom{
  border-top:1px solid var(--border);
  padding-top:24px;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  font-size:12px;color:var(--muted);letter-spacing:0.04em;
}
.footer-bottom .demo{color:var(--gold);font-style:italic;font-family:var(--serif)}

/* TOAST */
.toast-container{position:fixed;bottom:24px;right:24px;z-index:300;display:flex;flex-direction:column;gap:10px;max-width:340px}
.toast{
  background:linear-gradient(135deg,var(--velvet),var(--midnight));
  border:1px solid var(--gold);
  border-radius:3px;
  padding:14px 18px;
  display:flex;align-items:flex-start;gap:12px;
  box-shadow:0 12px 40px rgba(0,0,0,0.5);
  transform:translateX(120%);
  transition:transform .4s cubic-bezier(.2,.8,.2,1);
  animation:tick 2s infinite;
}
.toast.show{transform:translateX(0)}
.toast.err{border-color:#c0392b}
.toast .t-icon{font-size:18px;color:var(--gold);flex-shrink:0;margin-top:1px}
.toast.err .t-icon{color:#c0392b}
.toast .t-body{font-size:13px;color:var(--ivory);line-height:1.5}
.toast .t-title{font-weight:600;margin-bottom:2px}
.toast .t-msg{color:var(--muted)}
@keyframes tick{0%,100%{box-shadow:0 12px 40px rgba(0,0,0,0.5)}50%{box-shadow:0 12px 40px rgba(214,173,96,0.15)}}

/* SCROLL REVEAL */
.reveal{opacity:0;transform:translateY(30px)}
.reveal.visible{opacity:1;transform:none;transition:opacity .7s ease,transform .7s ease}
.reveal-delay-1{transition-delay:.1s}
.reveal-delay-2{transition-delay:.2s}
.reveal-delay-3{transition-delay:.3s}
.reveal-delay-4{transition-delay:.4s}

/* UTILS */
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}
@media(prefers-reduced-motion:reduce){
  *{animation:none!important;transition:none!important}
  html{scroll-behavior:auto}
}
</style>
</head>
