        <a href="#">Press</a>
        <a href="#">Contact</a>
      </div>
    </div>
    <div class="footer-bottom">
      <span>© 2026 ARTIFACT. All rights reserved.</span>
      <span class="demo">Demo landing page — no real ticket purchase.</span>
    </div>
  </div>
</footer>

<!-- ARTIST MODAL -->
<div class="modal-backdrop" id="artistModal" aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="artistModalTitle">
  <div class="modal" id="artistModalContent">
    <button class="modal-close" id="artistModalClose" aria-label="Close artist details">×</button>
    <img id="artistModalImg" src="" alt="" style="width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:2px;margin-bottom:20px;background:var(--velvet)">
    <h2 id="artistModalTitle"></h2>
    <div class="modal-sub" id="artistModalRole"></div>
    <p id="artistModalBio" style="font-size:14px;color:var(--muted);line-height:1.7;margin-bottom:18px"></p>
    <div style="display:flex;gap:10px;align-items:center;font-size:13px;color:var(--muted)">
      <span style="color:var(--gold);letter-spacing:0.1em;text-transform:uppercase;font-size:12px">Session</span>
      <span id="artistModalSession" style="color:var(--ivory)"></span>
    </div>
  </div>
</div>

<!-- TICKET MODAL -->
<div class="modal-backdrop" id="ticketModal" aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="ticketModalTitle">
  <div class="modal" id="ticketModalContent">
    <button class="modal-close" id="ticketModalClose" aria-label="Close ticket checkout">×</button>
    <h2 id="ticketModalTitle">Reserve your pass</h2>
    <div class="modal-sub" id="ticketModalSub">Complete the details below to hold your tickets. No payment is taken.</div>
    <form id="ticketForm" novalidate>
      <div id="ticketSelectedTier" style="display:none;background:var(--panel);border:1px solid var(--border);border-radius:2px;padding:12px 14px;margin-bottom:6px">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <span style="font-family:var(--serif);font-size:16px;color:var(--ivory)" id="ticketTierName"></span>
          <span style="color:var(--gold);font-family:var(--serif);font-size:18px" id="ticketTierPrice"></span>
        </div>
        <button type="button" id="ticketChangeTier" style="font-size:11px;color:var(--muted);letter-spacing:0.1em;text-transform:uppercase;margin-top:8px;background:none;border:none;text-decoration:underline">Choose a different tier</button>
      </div>
      <label>Attendee name</label>
      <input type="text" id="ticketName" placeholder="Full name" autocomplete="name">
      <label>Email address</label>
      <input type="email" id="ticketEmail" placeholder="you@email.com" autocomplete="email">
      <label>Number of tickets</label>
      <div class="modal-row">
        <input type="number" id="ticketQty" min="1" max="10" value="1" style="width:80px">
        <span style="color:var(--muted);font-size:13px;align-self:center">per reservation</span>
      </div>
      <div class="total">
        <span>Total</span>
        <strong id="ticketTotal">€0</strong>
      </div>
      <div class="terms">
        <input type="checkbox" id="ticketTerms">
        <label for="ticketTerms" style="margin:0;cursor:pointer">I understand this is a reservation mock — no payment is processed on this page.</label>
      </div>
      <button type="submit" class="modal-btn" id="ticketSubmit">Confirm reservation</button>
      <div id="ticketError" style="color:#c0392b;font-size:13px;margin-top:10px;display:none"></div>
    </form>
    <div id="ticketSuccess" class="modal-success" style="display:none">
      <div class="check">✓</div>
      <h3>You're on the list</h3>
      <p id="ticketSuccessMsg"></p>
      <p style="margin-top:14px">A confirmation has been prepared for your email. We'll be in touch closer to the evening.</p>
      <button type="button" id="ticketDone" class="modal-btn" style="margin-top:18px">Done</button>
    </div>
  </div>
</div>

<!-- TOAST -->
<div class="toast-container" id="toastContainer" aria-live="polite" aria-atomic="true"></div>

<script>
(function(){
  'use strict';

  // ---------- DATA ----------
  var artists = [
    { name:'Elena Voss', role:'Visual artist & curator', img:'https://source.unsplash.com/featured/1200x900?gallery,art', teaser:'Works on memory, dust, and the afterlife of objects.', bio:'Elena Voss is a Berlin-based visual artist whose installations treat museum storage as a kind of afterlife. For ARTIFACT she has assembled a small room of works never before shown publicly, each piece chosen for what it remembers rather than what it displays.', session:'20:00 — Hidden Collection Tour' },
    { name:'Marek Nowak', role:'Sound composer', img:'https://source.unsplash.com/featured/1200x900?exhibition,lights', teaser:'Ambient compositions for empty rooms.', bio:'Marek Nowak composes slow, room-sized sound for spaces that are otherwise quiet. His work for the evening was built by recording the Old Gallery itself at night, then writing around the hum of its radiators and the distance between its galleries.', session:'21:00 — Live Ambient Performance' },
    { name:'Sofia Reyes', role:'Sculpture artist', img:'https://source.unsplash.com/featured/1200x900?sculpture,museum', teaser:'Stone, shadow, and the weight of silence.', bio:'Sofia Reyes works in stone and plaster, favouring forms that seem to be remembering a shape they once held. Two of her pieces are installed in the Sculpture Hall for the projection evening, where light will move across their surfaces for the first time.', session:'22:00 — Sculpture Hall Projection' },
    { name:'Tomás Brandt', role:'Artist & writer', img:'https://source.unsplash.com/featured/1200x900?museum,crowd', teaser:'On crowds, distance, and looking alone.', bio:'Tomás Brandt writes and makes work about the experience of being alone in a crowded room. His artist talk for the evening is a meditation on the museum as a place where looking is both public and deeply private.', session:'23:00 — Artist Talk' },
    { name:'Aiko Tanaka', role:'Installation artist', img:'https://source.unsplash.com/featured/1200x900?art,installation', teaser:'Light as a material, darkness as a frame.', bio:'Aiko Tanaka builds installations out of light, fabric, and dust, treating each gallery as a room that can be gently re-invented. Her contribution to ARTIFACT is a small intervention in the main gallery, visible only during the midnight walk.', session:'00:00 — Midnight Gallery Walk' },
    { name:'David Halloran', role:'Sound artist', img:'https://source.unsplash.com/featured/1200x900?theater,stage', teaser:'The closing session, built from the evening itself.', bio:'David Halloran closes the night with a sound session assembled from recordings made throughout the evening — footsteps, low voices, the hum of the projection, the silence between segments. It is the museum speaking back to itself.', session:'01:00 — Closing Sound Session' },
    { name:'Nadia Koval', role:'Curator & art historian', img:'https://source.unsplash.com/featured/1200x900?gallery,art', teaser:'The keeper of what is kept out of sight.', bio:'Nadia Koval is the gallery’s chief curator and the mind behind the hidden collection tour. She has spent a decade learning the archive by heart, and for this evening she leads a small group through rooms that exist in the museum but not in its public story.', session:'19:30 — Curator Welcome' },
    { name:'Oskar Lindgren', role:'Projection designer', img:'https://source.unsplash.com/featured/1200x900?exhibition,lights', teaser:'Mapping light across old stone.', bio:'Oskar Lindgren designs slow projection pieces for buildings rather than screens. His work for the Sculpture Hall is built from the hall’s own proportions — a projection that takes the room as its subject and moves across it like a long, quiet thought.', session:'22:00 — Sculpture Hall Projection' }
  ];

  var ticketTiers = [
    { id:'night', name:'Night Pass', price:29, desc:'Entry to the evening’s public program.', features:['Entry after 19:00','Main exhibition access','Program access'], recommended:false },
    { id:'curator', name:'Curator Pass', price:59, desc:'For those who want the fuller evening.', features:['Everything in Night Pass','Hidden collection tour','Reserved artist talk seating'], recommended:true },
    { id:'patron', name:'Patron Pass', price:129, desc:'The complete evening, quietly arranged.', features:['Everything in Curator Pass','VIP lounge access','Signed event print','Priority entrance'], recommended:false }
  ];

  var faqs = [
    { q:'Is payment processed on this page?', a:'No. This is a demo landing page. Selecting a tier and confirming a reservation creates a mock booking only — no payment is taken and no real transaction occurs.' },
    { q:'Can I arrive late?', a:'Yes, with care. Late guests are admitted at the next natural break between program segments. We recommend arriving 15 minutes early to collect your map and welcome drink.' },
    { q:'Are photos allowed?', a:'Photography without flash is welcome in most galleries. A few rooms are photo-sensitive and will be marked at the entrance. Please respect the quiet of the evening.' },
    { q:'Is the venue accessible?', a:'Step-free access is available throughout the ground floor galleries, and a lift serves the upper exhibition level. Assistance is available on request at check-in.' },
    { q:'Can I change my ticket tier?', a:'If you have already reserved, contact us before the event and we will do our best to move you to a different tier, subject to availability.' },
    { q:'How do I save the event to my calendar?', a:'Use the “Save to Calendar” button in the hero section. It generates a downloadable .ics file you can open in any calendar application — no backend required.' }
  ];

  // ---------- RENDER ----------
  function renderArtists(){
    var grid = document.getElementById('artistsGrid');
    grid.innerHTML = artists.map(function(a,i){
      return '<div class="artist-card reveal reveal-delay-'+(i%4)+'" data-index="'+i+'" tabindex="0" role="button" aria-label="View details for '+a.name+'">'+
        '<img class="artist-img" src="'+a.img+'" alt="'+a.name+'" loading="lazy">'+
        '<div class="artist-body">'+
          '<div class="artist-name">'+a.name+'</div>'+
          '<div class="artist-role">'+a.role+'</div>'+
          '<div class="artist-teaser">'+a.teaser+'</div>'+
          '<span class="artist-link">View details →</span>'+
        '</div>'+
      '</div>';
    }).join('');
    grid.querySelectorAll('.artist-card').forEach(function(card){
      var open = function(){ openArtistModal(parseInt(card.dataset.index)); };
      card.addEventListener('click', open);
      card.addEventListener('keydown', function(e){
        if(e.key==='Enter' || e.key===' '){ e.preventDefault(); open(); }
      });
    });
  }

  function renderTickets(){
    var grid = document.getElementById('ticketsGrid');
    grid.innerHTML = ticketTiers.map(function(t){
      return '<div class="ticket'+(t.recommended?' recommended':'')+'" data-tier="'+t.id+'">'+
        (t.recommended?'<div class="ticket-rec">Recommended</div>':'')+
        '<div class="ticket-tier">'+t.name+'</div>'+
        '<div class="ticket-price">€'+t.price+'<small>per person</small></div>'+
        '<div class="ticket-desc">'+t.desc+'</div>'+
        '<ul class="ticket-features">'+t.features.map(function(f){ return '<li>'+f+'</li>'; }).join('')+'</ul>'+
        '<button class="ticket-btn" data-tier="'+t.id+'">Select '+t.name+'</button>'+
      '</div>';
    }).join('');
    grid.querySelectorAll('.ticket-btn').forEach(function(btn){
      btn.addEventListener('click', function(){
        selectTier(btn.dataset.tier);
      });
    });
  }

  function renderFAQ(){
    var list = document.getElementById('faqList');
    list.innerHTML = faqs.map(function(f,i){
      return '<div class="faq-item" data-i="'+i+'">'+
        '<button class="faq-q" aria-expanded="false" aria-controls="faq-a-'+i+'">'+
          '<span>'+f.q+'</span>'+
          '<span class="icon" aria-hidden="true">+</span>'+
        '</button>'+
        '<div class="faq-a" id="faq-a-'+i+'" role="region">'+
          '<div class="faq-a-inner">'+f.a+'</div>'+
        '</div>'+
      '</div>';
    }).join('');
    list.querySelectorAll('.faq-item').forEach(function(item){
      var btn = item.querySelector('.faq-q');
      btn.addEventListener('click', function(){
        var active = list.querySelector('.faq-item.active');
        if(active && active!==item){
          active.classList.remove('active');
          active.querySelector('.faq-q').setAttribute('aria-expanded','false');
          active.querySelector('.faq-a').style.maxHeight = '0px';
        }
        var expanded = item.classList.toggle('active');
        btn.setAttribute('aria-expanded', expanded?'true':'false');
        item.querySelector('.faq-a').style.maxHeight = expanded ? item.querySelector('.faq-a-inner').scrollHeight + 'px' : '0px';
      });
    });
  }

  // ---------- MODALS ----------
  var artistModal = document.getElementById('artistModal');
  var artistModalContent = document.getElementById('artistModalContent');
  var artistModalClose = document.getElementById('artistModalClose');
  var artistModalImg = document.getElementById('artistModalImg');
  var artistModalTitle = document.getElementById('artistModalTitle');
  var artistModalRole = document.getElementById('artistModalRole');
  var artistModalBio = document.getElementById('artistModalBio');
  var artistModalSession = document.getElementById('artistModalSession');

  function openArtistModal(i){
    var a = artists[i];
    artistModalImg.src = a.img;
    artistModalImg.alt = a.name;
    artistModalTitle.textContent = a.name;
    artistModalRole.textContent = a.role;
    artistModalBio.textContent = a.bio;
    artistModalSession.textContent = a.session;
    artistModal.classList.add('open');
    artistModal.setAttribute('aria-hidden','false');
    artistModalClose.focus();
    document.body.style.overflow = 'hidden';
  }
  function closeArtistModal(){
    artistModal.classList.remove('open');
    artistModal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
  }
  artistModalClose.addEventListener('click', closeArtistModal);
  artistModal.addEventListener('click', function(e){
    if(e.target === artistModal) closeArtistModal();
  });
  document.addEventListener('keydown', function(e){
    if(e.key==='Escape' && artistModal.classList.contains('open')) closeArtistModal();
  });

  // ---------- TICKET MODAL ----------
  var ticketModal = document.getElementById('ticketModal');
  var ticketModalClose = document.getElementById('ticketModalClose');
  var ticketForm = document.getElementById('ticketForm');
  var ticketSubmit = document.getElementById('ticketSubmit');
  var ticketSelectedTier = document.getElementById('ticketSelectedTier');
  var ticketTierName = document.getElementById('ticketTierName');
  var ticketTierPrice = document.getElementById('ticketTierPrice');
  var ticketTotal = document.getElementById('ticketTotal');
  var ticketQty = document.getElementById('ticketQty');
  var ticketName = document.getElementById('ticketName');
  var ticketEmail = document.getElementById('ticketEmail');
  var ticketTerms = document.getElementById('ticketTerms');
  var ticketError = document.getElementById('ticketError');
  var ticketSuccess = document.getElementById('ticketSuccess');
  var ticketSuccessMsg = document.getElementById('ticketSuccessMsg');
  var ticketDone = document.getElementById('ticketDone');
  var ticketChangeTier = document.getElementById('ticketChangeTier');
  var selectedTierId = null;

  function selectTier(id){
    selectedTierId = id;
    var t = ticketTiers.filter(function(x){return x.id===id;})[0];
    ticketTierName.textContent = t.name;
    ticketTierPrice.textContent = '€'+t.price;
    ticketTotal.textContent = '€'+(t.price * (parseInt(ticketQty.value,10)||1));
    ticketSelectedTier.style.display = 'block';
    openTicketModal();
  }

  function openTicketModal(){
    ticketModal.classList.add('open');
    ticketModal.setAttribute('aria-hidden','false');
    document.body.style.overflow = 'hidden';
    ticketSubmit.focus();
  }
  function closeTicketModal(){
    ticketModal.classList.remove('open');
    ticketModal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
  }
  ticketModalClose.addEventListener('click', closeTicketModal);
  ticketModal.addEventListener('click', function(e){
    if(e.target === ticketModal) closeTicketModal();
  });
  document.addEventListener('keydown', function(e){
    if(e.key==='Escape' && ticketModal.classList.contains('open')) closeTicketModal();
  });
  ticketChangeTier.addEventListener('click', function(){
    ticketSelectedTier.style.display = 'none';
    ticketModalTitle.textContent = 'Reserve your pass';
    ticketModalSub.style.display = '';
    ticketForm.style.display = '';
    ticketSuccess.style.display = 'none';
    ticketError.style.display = 'none';
    ticketSubmit.textContent = 'Confirm reservation';
    ticketSubmit.disabled = false;
    setTimeout(function(){ ticketModalClose.focus(); }, 50);
  });

  ticketQty.addEventListener('input', function(){
    if(selectedTierId){
      var t = ticketTiers.filter(function(x){return x.id===selectedTierId;})[0];
      ticketTotal.textContent = '€'+(t.price * (parseInt(ticketQty.value,10)||1));
    }
  });

  ticketForm.addEventListener('submit', function(e){
    e.preventDefault();
    ticketError.style.display = 'none';
    var name = ticketName.value.trim();
    var email = ticketEmail.value.trim();
    var qty = parseInt(ticketQty.value,10);
    var terms = ticketTerms.checked;

    if(!name){ setTicketError('Please enter your name.'); focusField(ticketName); return; }
    if(!email || !isValidEmail(email)){ setTicketError('Please enter a valid email address.'); focusField(ticketEmail); return; }
    if(!qty || qty < 1){ setTicketError('Please choose at least one ticket.'); focusField(ticketQty); return; }
    if(!terms){ setTicketError('Please accept the terms to continue.'); ticketTerms.focus(); return; }

    var t = ticketTiers.filter(function(x){return x.id===selectedTierId;})[0];
    var total = t.price * qty;
    ticketSubmit.disabled = true;
    ticketSubmit.textContent = 'Reserving…';

    setTimeout(function(){
      ticketForm.style.display = 'none';
      ticketSuccess.style.display = 'block';
      ticketSuccessMsg.textContent = 'Reservation held for '+qty+' '+(qty===1?'ticket':'tickets')+' — '+t.name+' (€'+total+'). No payment has been taken.';
      showToast({ title:'Reservation held', msg:t.name+' — €'+total+'. No payment taken.', type:'success' });
    }, 600);
  });

  function setTicketError(msg){
    ticketError.textContent = msg;
    ticketError.style.display = 'block';
  }
  function focusField(el){
    setTimeout(function(){ el.focus(); el.classList.add('error'); }, 10);
  }
  function isValidEmail(v){
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
  }
  ticketDone.addEventListener('click', function(){
    ticketSuccess.style.display = 'none';
    ticketModalTitle.textContent = 'Reserve your pass';
    ticketModalSub.style.display = '';
    ticketForm.style.display = '';
    ticketSelectedTier.style.display = 'none';
    ticketSubmit.disabled = false;
    ticketSubmit.textContent = 'Confirm reservation';
    ticketName.value = '';
    ticketEmail.value = '';
    ticketQty.value = '1';
    ticketTerms.checked = false;
    selectedTierId = null;
    closeTicketModal();
  });

  // ---------- TOAST ----------
  var toastContainer = document.getElementById('toastContainer');
  function showToast({title,msg,type}){
    var el = document.createElement('div');
    el.className = 'toast'+(type==='error'?' err':'');
    el.innerHTML = '<span class="t-icon">'+(type==='error'?'✕':'✓')+'</span>'+
      '<div class="t-body"><div class="t-title">'+title+'</div><div class="t-msg">'+msg+'</div></div>';
    toastContainer.appendChild(el);
    requestAnimationFrame(function(){ el.classList.add('show'); });
    setTimeout(function(){
      el.classList.remove('show');
      setTimeout(function(){ el.remove(); }, 400);
    }, 4200);
  }

  // ---------- NEWSLETTER ----------
  var newsletterForm = document.getElementById('newsletterForm');
  var newsletterEmail = document.getElementById('newsletterEmail');
  newsletterForm.addEventListener('submit', function(e){
    e.preventDefault();
    var v = newsletterEmail.value.trim();
    newsletterEmail.classList.remove('error');
    if(!v || !isValidEmail(v)){
      newsletterEmail.classList.add('error');
      showToast({ title:'Invalid email', msg:'Please enter a valid email address.', type:'error' });
      newsletterEmail.focus();
      return;
    }
    showToast({ title:'You’re on the list', msg:'Thank you — we’ll be in touch with quiet notes.', type:'success' });
    newsletterEmail.value = '';
  });

  // ---------- CALENDAR ----------
  function downloadICS(){
    var start = '20261018T190000';
    var end = '20261019T020000';
    var nl = '\r\n';
    var ics =
      'BEGIN:VCALENDAR'+nl+
      'VERSION:2.0'+nl+
      'PRODID:-//ARTIFACT//Museum Night//EN'+nl+
      'CALSCALE:GREGORIAN'+nl+
      'METHOD:PUBLISH'+nl+
      'BEGIN:VEVENT'+nl+
      'DTSTART:'+start+nl+
      'DTEND:'+end+nl+
      'SUMMARY:ARTIFACT: Museum Night'+nl+
      'LOCATION:The Old Gallery, Warsaw'+nl+
      'DESCRIPTION:A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.'+nl+
      'UID:artifact-museum-night-2026@artifact'+nl+
      'END:VEVENT'+nl+
      'END:VCALENDAR';
    var blob = new Blob([ics], { type:'text/calendar;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'artifact-museum-night.ics';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(url); }, 1000);
    showToast({ title:'Calendar file ready', msg:'artifact-museum-night.ics downloaded. Open it to add the event.', type:'success' });
  }
  document.getElementById('heroCalendar').addEventListener('click', downloadICS);

  // ---------- NAV ACTIVE STATE ----------
  var navLinks = document.querySelectorAll('.nav-links a[data-nav]');
  var sections = ['program','artists','venue','tickets','faq'].map(function(id){
    return document.getElementById(id);
  });
  function updateNav(){
    var scrollY = window.scrollY + 120;
    var current = 'hero';
    for(var i=0;i<sections.length;i++){
      if(sections[i] && sections[i].offsetTop <= scrollY) current = ['program','artists','venue','tickets','faq'][i];
    }
    navLinks.forEach(function(a){
      a.classList.toggle('active', a.dataset.nav === current);
    });
  }
  window.addEventListener('scroll', updateNav, { passive:true });
  updateNav();

  // ---------- MOBILE MENU ----------
  var menuToggle = document.getElementById('menuToggle');
  var navLinksEl = document.getElementById('navLinks');
  menuToggle.addEventListener('click', function(){
    var open = navLinksEl.classList.toggle('open');
    menuToggle.setAttribute('aria-expanded', open?'true':'false');
    menuToggle.textContent = open?'✕':'☰';
  });
  navLinksEl.querySelectorAll('a').forEach(function(a){
    a.addEventListener('click', function(){
      navLinksEl.classList.remove('open');
      menuToggle.setAttribute('aria-expanded','false');
      menuToggle.textContent = '☰';
    });
  });

  // ---------- SCROLL REVEAL ----------
  var revealEls = document.querySelectorAll('.reveal');
  var revealObserver = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){
        e.target.classList.add('visible');
        revealObserver.unobserve(e.target);
      }
    });
  }, { threshold:0.12, rootMargin:'0px 0px -40px 0px' });
  revealEls.forEach(function(el){ revealObserver.observe(el); });

  // timeline items reveal on scroll with a slight delay per item
  var tlItems = document.querySelectorAll('#timeline .timeline-item');
  var tlObserver = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){
        e.target.classList.add('revealed');
        tlObserver.unobserve(e.target);
      }
    });
  }, { threshold:0.2 });
  tlItems.forEach(function(el){ tlObserver.observe(el); });

  // ---------- SMOOTH SCROLL FOR IN-PAGE ANCHORS ----------
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      var id = a.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if(el){
        e.preventDefault();
        var top = el.getBoundingClientRect().top + window.scrollY - 70;
        window.scrollTo({ top: top, behavior:'smooth' });
      }
    });
  });

  // ---------- INIT ----------
  renderArtists();
  renderTickets();
  renderFAQ();

  // preload hero image eagerly
  var heroImg = document.querySelector('.hero-img');
  if(heroImg.complete && heroImg.naturalWidth===0){
    // if broken, keep layout stable — image is decorative
  }
})();
</script>
</body>
</html>
